(() => {
'use strict';
const $=id=>document.getElementById(id), core=()=>window.DashboardCore;
const s={client:null,user:null,profile:null,resources:[],interests:[],stats:new Map(),liked:new Set(),busy:new Set(),lastStats:'',epoch:0,thread:null,comments:[],page:0,signUp:false,loading:false,commentRequest:0};
function notice(message){core()?.toast(message)}
function message(error){const code=error?.code||'',t=error?.message||'';if(code==='23505')return '이미 등록한 자료이거나 이미 누른 반응입니다.';if(/invalid login/i.test(t))return '이메일 또는 비밀번호를 확인해 주세요.';if(/email not confirmed/i.test(t))return '이메일 확인이 필요합니다. 받은 메일을 확인해 주세요.';if(/email.*rate|rate.*limit|over_email/i.test(t+' '+code))return '요청이 많습니다. 잠시 후 다시 시도해 주세요.';if(/schema cache|does not exist|42501|permission denied|row.level/i.test(t+' '+code))return '커뮤니티 설정을 확인해 주세요. 새로고침해도 같으면 관리자에게 알려주세요.';if(/fetch|network/i.test(t))return '서버에 연결하지 못했습니다. 인터넷 연결 후 다시 시도해 주세요.';return t||'저장하지 못했습니다. 잠시 후 다시 시도해 주세요.'}
function configError(config){if(!config?.url||!config?.publishableKey)return '아직 커뮤니티가 연결되지 않았습니다.';try{const u=new URL(config.url);if(u.protocol!=='https:'||u.username||u.password||!u.hostname.endsWith('.supabase.co')||!['','/'].includes(u.pathname))return '커뮤니티 주소 설정을 확인해 주세요.';}catch{return '커뮤니티 주소 설정을 확인해 주세요.'}if(!/^sb_publishable_[A-Za-z0-9_-]+$/.test(config.publishableKey))return '공개용 publishable 키 설정을 확인해 주세요.';return ''}
function rowFromDB(row){return {...row,community:true,collected_at:row.created_at,published_at:null,tag_method:'manual',auto_tags:[],hidden:false,contributor:row.defi_profiles?.display_name||'이용자'}}
function requireUser(){if(!s.client){notice('아직 커뮤니티가 연결되지 않았습니다.');return false}if(!s.user){openAuth();return false}return true}
function refresh(){s.lastStats='';core()?.render()}
function button(text,run,className=''){const b=document.createElement('button');b.type='button';b.textContent=text;b.className=className;b.onclick=run;return b}
function line(tag,text,className=''){const n=document.createElement(tag);n.textContent=text;n.className=className;return n}
function renderAccount(){const b=$('account-menu');b.textContent=s.user?(s.profile?.display_name||'내 계정'):'로그인';$('community-status').textContent=s.client?'자료와 댓글은 모두에게 공개되며, 관심 협의회는 본인에게만 보입니다.':'커뮤니티 연결 전입니다. 자료 열람과 브라우저 저장을 이용할 수 있습니다.';$('comment-body').disabled=!s.user;$('comment-submit').disabled=!s.user;$('comment-login').hidden=!!s.user;$('comment-form-help').textContent=s.user?'최대 2,000자 · 닉네임과 함께 공개됩니다.':'댓글을 작성하려면 로그인해 주세요.';}
function openAuth(){if(!s.client){notice('아직 커뮤니티가 연결되지 않았습니다.');return}if(s.user){$('profile-name').value=s.profile?.display_name||'이용자';$('profile-error').textContent='';$('profile-dialog').showModal();return}$('auth-error').textContent='';$('auth-dialog').showModal()}
function authMode(signUp){s.signUp=signUp;$('signup-fields').hidden=!signUp;$('auth-name').required=signUp;$('auth-title').textContent=signUp?'회원가입':'로그인';$('auth-submit').textContent=signUp?'가입하기':'로그인';$('auth-switch').textContent=signUp?'이미 계정이 있어요 · 로그인':'처음 방문했어요 · 회원가입';$('auth-password').autocomplete=signUp?'new-password':'current-password';$('auth-password').minLength=signUp?8:1;$('auth-error').textContent=''}
async function loadPublic(){if(!s.client)return;const epoch=s.epoch;const {data,error}=await s.client.from('defi_resources').select('*,defi_profiles(display_name)').order('created_at',{ascending:false}).limit(500);if(epoch!==s.epoch)return;if(error)throw error;s.resources=(data||[]).map(rowFromDB)}
async function loadPersonal(){const user=s.user,epoch=s.epoch;if(!user){s.profile=null;s.interests=[];s.liked.clear();return}const [p,i]=await Promise.all([s.client.from('defi_profiles').select('display_name').eq('id',user.id).single(),s.client.from('defi_interests').select('council_ids').eq('user_id',user.id).maybeSingle()]);if(epoch!==s.epoch)return;if(p.error)throw p.error;if(i.error)throw i.error;s.profile=p.data;s.interests=i.data?.council_ids||[];s.liked.clear()}
async function authChanged(user){s.epoch++;s.user=user;s.profile=null;s.interests=[];s.liked.clear();s.lastStats='';if(core())core().state.interestsOnly=false;renderAccount();try{await loadPersonal()}catch(e){notice(message(e))}renderAccount();if($('thread-dialog').open)renderComments();refresh()}
async function loadStats(){if(!s.client||!core())return;const ids=core().filteredResources().slice(0,core().state.limit).map(r=>r.id),key=(s.user?.id||'anon')+':'+ids.join(',');if(key===s.lastStats)return;s.lastStats=key;if(!ids.length)return;const epoch=s.epoch;try{const chunks=[];for(let offset=0;offset<ids.length;offset+=100)chunks.push(ids.slice(offset,offset+100));const parts=await Promise.all(chunks.map(async group=>{const stats=await s.client.rpc('defi_resource_stats',{p_ids:group});if(stats.error)throw stats.error;let likes=[];if(s.user){const r=await s.client.from('defi_likes').select('resource_id').eq('user_id',s.user.id).in('resource_id',group);if(r.error)throw r.error;likes=r.data||[]}return {stats:stats.data||[],likes}}));const data=parts.flatMap(p=>p.stats),likes=parts.flatMap(p=>p.likes);if(epoch!==s.epoch||key!==s.lastStats)return;for(const row of data||[])s.stats.set(row.resource_id,row);for(const id of ids)s.liked.delete(id);for(const row of likes)s.liked.add(row.resource_id);core().render()}catch(e){notice(message(e))}}
function decorateCard(body,row){const footer=document.createElement('div');footer.className='community-actions';const stats=s.stats.get(row.id),liked=s.liked.has(row.id);const like=button('♡ 유용해요'+(stats?' '+stats.like_count:''),()=>toggleLike(row.id),liked?'is-liked':'');like.setAttribute('aria-pressed',String(liked));like.disabled=s.busy.has(row.id);footer.append(button('댓글'+(stats?' '+stats.comment_count:''),()=>openThread(row)),like);if(row.community){footer.append(line('span',row.contributor+' 공유','contributor'));if(s.user?.id===row.owner_id){footer.append(button('수정',()=>core().openEditor(row)),button('삭제',()=>deleteResource(row)))}}body.append(footer)}
function afterRender(){const resources=core()?.effectiveResources()||[];const ids=new Set(s.interests);$('interested-count').textContent=resources.filter(r=>r.tags?.some(t=>ids.has(t))).length;$('interested-resources').classList.toggle('active',!!core()?.state.interestsOnly);if(core()?.state.interestsOnly){$('view-title').textContent='관심 협의회 자료';$('view-description').textContent=s.interests.length?'선택한 협의회와 관련된 자료를 모았습니다.':'관심 협의회를 설정하면 관련 자료가 여기에 표시됩니다.'}Promise.resolve().then(loadStats)}
async function toggleLike(id){if(!requireUser()||s.busy.has(id))return;s.busy.add(id);core().render();try{const user=s.user.id,old=s.liked.has(id);const r=old?await s.client.from('defi_likes').delete().eq('resource_id',id).eq('user_id',user):await s.client.from('defi_likes').insert({resource_id:id,user_id:user});if(r.error&&r.error.code!=='23505')throw r.error;if(s.user?.id===user){if(old)s.liked.delete(id);else s.liked.add(id)}s.lastStats=''}catch(e){notice(message(e))}finally{s.busy.delete(id);core().render()}}
function beginAdd(){if(requireUser())core().openEditor(null)}
function editorOpened(row){const shared=s.client&&(!row||row.community&&s.user?.id===row.owner_id);$('editor-save').textContent=shared?(row?'공유 자료 수정':'모두에게 자료 등록'):'이 브라우저에 저장';$('editor-scope').textContent=shared?'저장하면 다른 방문자도 볼 수 있습니다.':'직접 고른 RSS 태그는 이 브라우저에 저장됩니다. 공개 반영은 편집 파일 내보내기를 이용하세요.'}
async function saveResource(fields,resource){if(!requireUser())throw Error('로그인 후 이용해 주세요.');const user=s.user.id,url=core().validURL($('edit-url').value.trim()),id=resource?.id||await core().resourceID(url);if(!resource&&core().effectiveResources().some(r=>r.id===id||r.url===url))throw Error('이미 모아본 자료에 있는 링크입니다. 해당 자료에 댓글을 남겨보세요.');const values={...core().cleanOverride(fields),source:$('edit-source').value.trim().slice(0,80)||'이용자 공유'};delete values.hidden;const r=resource?await s.client.from('defi_resources').update(values).eq('id',id).eq('owner_id',user).select('id'):await s.client.from('defi_resources').insert({...values,id,url,owner_id:user}).select('id');if(r.error)throw r.error;if(!r.data?.length)throw Error('수정할 수 있는 자료가 없습니다.');await loadPublic();refresh();notice(resource?'공유 자료를 수정했습니다.':'자료를 등록했습니다. 다른 방문자도 볼 수 있습니다.')}
async function deleteResource(row){if(!requireUser()||s.user.id!==row.owner_id)return;if(!window.confirm('이 자료와 연결된 댓글·유용해요를 삭제할까요?'))return;try{const r=await s.client.from('defi_resources').delete().eq('id',row.id).eq('owner_id',s.user.id).select('id');if(r.error)throw r.error;if(!r.data?.length)throw Error('삭제할 수 있는 자료가 없습니다.');await loadPublic();refresh();notice('공유 자료를 삭제했습니다.')}catch(e){notice(message(e))}}
function openInterests(){if(!requireUser())return;const list=$('interest-options');list.replaceChildren();for(const council of core().state.catalog.councils){const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=council.id;box.checked=s.interests.includes(council.id);label.append(box,document.createTextNode(council.label));list.append(label)}$('interests-error').textContent='';$('interests-dialog').showModal()}
async function openThread(row){s.thread=row;s.page=0;s.comments=[];$('thread-comments').replaceChildren(line('p','댓글을 불러오는 중입니다.','note'));$('comments-more').hidden=true;$('thread-title').textContent=row.title;$('thread-link').href=core().validURL(row.url);$('comment-body').value='';$('thread-error').textContent='';$('thread-dialog').showModal();renderAccount();await loadComments(true)}
async function loadComments(reset=false){if(!s.thread)return;const id=s.thread.id;if(!s.client){$('thread-comments').replaceChildren(line('p','커뮤니티 연결 후 댓글을 확인할 수 있습니다.','note'));$('comments-more').hidden=true;return}if(s.loading&&!reset)return;const request=++s.commentRequest;s.loading=true;try{const page=reset?0:s.page,r=await s.client.from('defi_comments').select('id,resource_id,author_id,body,created_at,updated_at,defi_profiles(display_name)').eq('resource_id',id).order('created_at',{ascending:false}).order('id',{ascending:false}).range(page*30,page*30+29);if(r.error)throw r.error;if(s.thread?.id!==id||request!==s.commentRequest)return;s.comments=reset?(r.data||[]):[...s.comments,...(r.data||[])];s.page=page+1;renderComments();$('comments-more').hidden=(r.data||[]).length<30;$('thread-error').textContent=''}catch(e){$('thread-error').textContent=message(e)}finally{if(request===s.commentRequest)s.loading=false}}
function renderComments(){const list=$('thread-comments');list.replaceChildren();if(!s.comments.length)list.append(line('p','첫 의견을 남겨보세요.','note'));for(const comment of s.comments){const article=document.createElement('article');article.className='thread-comment';article.append(line('b',comment.defi_profiles?.display_name||'이용자'),line('small',new Date(comment.created_at).toLocaleString('ko-KR')+(comment.updated_at!==comment.created_at?' · 수정됨':'')),line('p',comment.body));if(s.user?.id===comment.author_id){const tools=document.createElement('div');tools.className='comment-tools';tools.append(button('수정',()=>editComment(article,comment)),button('삭제',()=>removeComment(comment)));article.append(tools)}list.append(article)}}
function editComment(article,comment){const input=document.createElement('textarea');input.value=comment.body;input.maxLength=2000;input.rows=4;article.replaceChildren(input,button('수정 저장',async()=>{if(!input.value.trim())return;try{const r=await s.client.from('defi_comments').update({body:input.value.trim()}).eq('id',comment.id).eq('author_id',s.user.id).select('id');if(r.error)throw r.error;if(!r.data?.length)throw Error('수정할 수 있는 댓글이 없습니다.');await loadComments(true)}catch(e){$('thread-error').textContent=message(e)}}),button('취소',renderComments))}
async function removeComment(comment){if(!window.confirm('내 댓글을 삭제할까요?'))return;try{const r=await s.client.from('defi_comments').delete().eq('id',comment.id).eq('author_id',s.user.id).select('id');if(r.error)throw r.error;await loadComments(true);refresh()}catch(e){$('thread-error').textContent=message(e)}}
async function refreshAll(){if(!s.client)return;try{await loadPublic();await loadPersonal();refresh();renderAccount();if($('thread-dialog').open)await loadComments(true)}catch(e){notice(message(e))}}
$('account-menu').onclick=openAuth;$('close-auth').onclick=()=>$('auth-dialog').close();$('auth-switch').onclick=()=>authMode(!s.signUp);
$('auth-form').onsubmit=async event=>{event.preventDefault();const b=$('auth-submit');b.disabled=true;$('auth-error').textContent='';try{const email=$('auth-email').value.trim(),password=$('auth-password').value;const name=$('auth-name').value.trim();if(s.signUp&&(name.length<2||name.length>30))throw Error('닉네임은 2~30자로 입력해 주세요.');const r=s.signUp?await s.client.auth.signUp({email,password,options:{data:{display_name:name},emailRedirectTo:location.origin+location.pathname}}):await s.client.auth.signInWithPassword({email,password});if(r.error)throw r.error;$('auth-password').value='';if(r.data.session){$('auth-dialog').close();await authChanged(r.data.session.user);notice('로그인했습니다.')}else $('auth-error').textContent='가입 확인 메일을 확인해 주세요. 메일이 오지 않으면 관리자에게 문의해 주세요.';}catch(e){$('auth-error').textContent=message(e)}finally{b.disabled=false}};
$('close-profile').onclick=()=>$('profile-dialog').close();$('profile-interests').onclick=()=>{$('profile-dialog').close();openInterests()};$('profile-form').onsubmit=async e=>{e.preventDefault();try{const name=$('profile-name').value.trim();if(name.length<2||name.length>30)throw Error('닉네임은 2~30자로 입력해 주세요.');const r=await s.client.from('defi_profiles').update({display_name:name}).eq('id',s.user.id).select('display_name').single();if(r.error)throw r.error;s.profile=r.data;renderAccount();$('profile-dialog').close();await loadPublic();refresh()}catch(error){$('profile-error').textContent=message(error)}};
$('logout').onclick=async()=>{const r=await s.client.auth.signOut();if(r.error){notice(message(r.error));return}$('profile-dialog').close();await authChanged(null)};
$('open-withdrawal').onclick=()=>{if(!requireUser())return;$('profile-dialog').close();$('withdrawal-password').value='';$('withdrawal-confirmation').value='';$('withdrawal-error').textContent='';$('withdrawal-dialog').showModal()};
$('close-withdrawal').onclick=()=>{if($('withdrawal-submit').disabled)return;$('withdrawal-password').value='';$('withdrawal-dialog').close()};
$('withdrawal-dialog').addEventListener('cancel',event=>{if($('withdrawal-submit').disabled){event.preventDefault();return}$('withdrawal-password').value=''});
$('withdrawal-form').onsubmit=async event=>{event.preventDefault();if($('withdrawal-submit').disabled||!requireUser())return;const b=$('withdrawal-submit');b.disabled=true;$('withdrawal-error').textContent='';try{if($('withdrawal-confirmation').value.trim()!=='탈퇴')throw Error('확인란에 탈퇴를 입력해 주세요.');const departingUser=s.user.id;const password=$('withdrawal-password').value;if(!password)throw Error('현재 비밀번호를 입력해 주세요.');const {data,error}=await s.client.functions.invoke('delete-account',{body:{password,confirmation:'탈퇴'}});if(error){let detail;try{detail=await error.context?.json()}catch{}throw Error(detail?.error||'탈퇴를 완료하지 못했습니다. 잠시 후 다시 시도해 주세요.')}if(data?.deleted!==true)throw Error('탈퇴 완료 여부를 확인하지 못했습니다.');try{await s.client.auth.signOut({scope:'local'})}catch{}await authChanged(null);core().clearBrowserData();$('withdrawal-dialog').close();$('thread-dialog').close();s.thread=null;s.comments=[];s.stats.clear();s.resources=s.resources.filter(r=>r.owner_id!==departingUser);try{await loadPublic()}catch{}refresh();notice('회원 탈퇴가 완료됐습니다. 계정과 작성 내용이 삭제됐습니다.')}catch(error){$('withdrawal-error').textContent=message(error)}finally{$('withdrawal-password').value='';b.disabled=false}};
$('interest-settings').onclick=openInterests;$('close-interests').onclick=()=>$('interests-dialog').close();$('interested-resources').onclick=()=>{if(!requireUser())return;core().state.council='all';core().state.savedOnly=false;core().state.interestsOnly=true;core().state.limit=20;location.hash='#resources';core().render()};
$('interests-form').onsubmit=async e=>{e.preventDefault();const b=$('interests-save');b.disabled=true;try{const user=s.user.id,ids=[...$('interest-options').querySelectorAll('input:checked')].map(n=>n.value);const r=await s.client.from('defi_interests').upsert({user_id:user,council_ids:ids},{onConflict:'user_id'});if(r.error)throw r.error;if(s.user?.id===user)s.interests=ids;$('interests-dialog').close();refresh();notice('관심 협의회를 계정에 저장했습니다.')}catch(error){$('interests-error').textContent=message(error)}finally{b.disabled=false}};
$('close-thread').onclick=()=>{$('thread-dialog').close();s.thread=null};$('comment-login').onclick=openAuth;$('comments-refresh').onclick=()=>loadComments(true);$('comments-more').onclick=()=>loadComments(false);
$('comment-form').onsubmit=async e=>{e.preventDefault();if(!requireUser()||!s.thread)return;const b=$('comment-submit');b.disabled=true;try{const body=$('comment-body').value.trim();if(!body||body.length>2000)throw Error('댓글은 1~2,000자로 입력해 주세요.');const id=s.thread.id,r=await s.client.from('defi_comments').insert({resource_id:id,author_id:s.user.id,body});if(r.error)throw r.error;if(s.thread?.id===id){$('comment-body').value='';await loadComments(true)}refresh()}catch(error){$('thread-error').textContent=message(error)}finally{b.disabled=!s.user}};
const previousRefresh=$('resources-refresh').onclick;$('resources-refresh').onclick=async()=>{await previousRefresh();await refreshAll()};
window.Community={get resources(){return s.resources},get interests(){return s.interests},get connected(){return !!s.client},get user(){return s.user},decorateCard,afterRender,beginAdd,editorOpened,saveResource,refreshAll,configError};
async function init(){authMode(false);renderAccount();const error=configError(window.DEFI_SUPABASE);if(error){core()?.render();return}if(!window.supabase?.createClient){notice('로그인 기능을 불러오지 못했습니다. 새로고침해 주세요.');return}try{s.client=window.supabase.createClient(window.DEFI_SUPABASE.url,window.DEFI_SUPABASE.publishableKey,{auth:{detectSessionInUrl:false}});const {data,error}=await s.client.auth.getSession();if(error)throw error;s.user=data.session?.user||null;await Promise.all([loadPublic(),loadPersonal()]);renderAccount();refresh();s.client.auth.onAuthStateChange((event,session)=>{if((session?.user?.id||null)!==(s.user?.id||null))setTimeout(()=>{if((session?.user?.id||null)!==(s.user?.id||null))authChanged(session?.user||null)},0)})}catch(e){notice(message(e));renderAccount();refresh()}}
init();
})();
